"use client";

import { useEffect, useRef } from "react";
import "./status-label-handoff.css";

export type StatusLabelTone = "neutral" | "active" | "success" | "warning";

export interface StatusLabelHandoffProps {
  label: string;
  tone?: StatusLabelTone;
  className?: string;
}

export function StatusLabelHandoff({
  label,
  tone = "neutral",
  className = "",
}: StatusLabelHandoffProps) {
  const current = label.trim() || "Unknown status";
  const previous = useRef(current);
  const changed = previous.current !== current;
  const toneLabel: Record<StatusLabelTone, string> = {
    neutral: "neutral",
    active: "active",
    success: "successful",
    warning: "warning",
  };

  useEffect(() => {
    previous.current = current;
  }, [current]);

  return (
    <span
      className={`tb-status-label-handoff ${className}`.trim()}
      data-tone={tone}
      role="status"
      aria-live="polite"
    >
      <span className="tb-status-label-handoff__sr">
        Status: {current}. State tone: {toneLabel[tone]}.
      </span>
      <span className="tb-status-label-handoff__marker" aria-hidden="true" />
      <span className="tb-status-label-handoff__viewport" aria-hidden="true">
        <span
          className={changed ? "tb-status-label-handoff__new" : ""}
          key={current}
        >
          {current}
        </span>
      </span>
    </span>
  );
}

export default StatusLabelHandoff;

.tb-status-label-handoff {
  --tb-status-color: #272b28;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  min-height: 36px;
  padding: 0 13px;
  border: 1px solid color-mix(in srgb, var(--tb-status-color), transparent 56%);
  border-radius: 999px;
  color: var(--tb-status-color);
  background: color-mix(in srgb, var(--tb-status-color), transparent 91%);
  font: 650 0.82rem / 1 system-ui, sans-serif;
  width: max-content;
}

.tb-status-label-handoff[data-tone="active"] { --tb-status-color: #2354c7; }
.tb-status-label-handoff[data-tone="success"] { --tb-status-color: #197047; }
.tb-status-label-handoff[data-tone="warning"] { --tb-status-color: #8c4a12; }

.tb-status-label-handoff__marker {
  display: inline-grid;
  width: 1em;
  height: 1em;
  place-items: center;
  font-weight: 800;
  line-height: 1;
}

.tb-status-label-handoff__marker::before { content: "•"; }
.tb-status-label-handoff[data-tone="active"] .tb-status-label-handoff__marker::before { content: "→"; }
.tb-status-label-handoff[data-tone="success"] .tb-status-label-handoff__marker::before { content: "✓"; }
.tb-status-label-handoff[data-tone="warning"] .tb-status-label-handoff__marker::before { content: "!"; }

.tb-status-label-handoff__viewport {
  display: inline-grid;
  overflow: hidden;
}

.tb-status-label-handoff__viewport > span {
  grid-area: 1 / 1;
  white-space: nowrap;
}

.tb-status-label-handoff__new {
  animation: tb-status-new 160ms cubic-bezier(0.22, 1, 0.36, 1) both;
}

.tb-status-label-handoff__sr {
  position: absolute;
  width: 1px;
  height: 1px;
  padding: 0;
  margin: -1px;
  overflow: hidden;
  clip: rect(0, 0, 0, 0);
  white-space: nowrap;
  border: 0;
}

@keyframes tb-status-new {
  from { opacity: 0; transform: translateY(35%); }
}

@media (prefers-reduced-motion: reduce) {
  .tb-status-label-handoff__new {
    animation: none;
  }
}

@media (forced-colors: active) {
  .tb-status-label-handoff {
    border-color: ButtonText;
    color: ButtonText;
    background: ButtonFace;
  }
}
